// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListFaults Сбои источников на стенде
	// (GET /admin/faults)
	ListFaults(ctx echo.Context) error
	// SetFault Включить или снять сбой источника
	// (PUT /admin/faults)
	SetFault(ctx echo.Context) error
	// ListApplications Список заявок
	// (GET /applications)
	ListApplications(ctx echo.Context, params ListApplicationsParams) error
	// CreateApplication Создать черновик
	// (POST /applications)
	CreateApplication(ctx echo.Context, params CreateApplicationParams) error
	// GetApplication Карточка заявки
	// (GET /applications/{id})
	GetApplication(ctx echo.Context, id ApplicationID) error
	// UpdateApplication Изменить черновик
	// (PATCH /applications/{id})
	UpdateApplication(ctx echo.Context, id ApplicationID) error
	// AcceptOffer Принять условия
	// (POST /applications/{id}/accept)
	AcceptOffer(ctx echo.Context, id ApplicationID) error
	// CancelApplication Отменить заявку или отказаться от условий
	// (POST /applications/{id}/cancel)
	CancelApplication(ctx echo.Context, id ApplicationID) error
	// DecideApplication Решение андеррайтера
	// (POST /applications/{id}/decision)
	DecideApplication(ctx echo.Context, id ApplicationID) error
	// UploadDocument Загрузить документ
	// (POST /applications/{id}/documents)
	UploadDocument(ctx echo.Context, id ApplicationID) error
	// ListApplicationEvents Журнал аудита заявки
	// (GET /applications/{id}/history)
	ListApplicationEvents(ctx echo.Context, id ApplicationID) error
	// ProvideInfo Ответить на запрос уточнений
	// (POST /applications/{id}/provide-info)
	ProvideInfo(ctx echo.Context, id ApplicationID) error
	// RequestInfo Запросить документы или уточнения
	// (POST /applications/{id}/request-info)
	RequestInfo(ctx echo.Context, id ApplicationID) error
	// RetryChecks Повторить проверки
	// (POST /applications/{id}/retry-checks)
	RetryChecks(ctx echo.Context, id ApplicationID) error
	// SignApplication Подписать кодом
	// (POST /applications/{id}/sign)
	SignApplication(ctx echo.Context, id ApplicationID) error
	// RequestSigningCode Получить код подписания
	// (POST /applications/{id}/signing-code)
	RequestSigningCode(ctx echo.Context, id ApplicationID) error
	// SubmitApplication Подать заявку
	// (POST /applications/{id}/submit)
	SubmitApplication(ctx echo.Context, id ApplicationID) error
	// LookupCompany Автоподстановка по ИНН
	// (GET /companies/{inn})
	LookupCompany(ctx echo.Context, inn INN) error
	// GetDocument Документ и результат распознавания
	// (GET /documents/{id})
	GetDocument(ctx echo.Context, id DocumentID) error
	// ConfirmDocument Подтвердить значения документа
	// (POST /documents/{id}/confirm)
	ConfirmDocument(ctx echo.Context, id DocumentID) error
	// DownloadDocument Файл документа
	// (GET /documents/{id}/file)
	DownloadDocument(ctx echo.Context, id DocumentID) error
	// ListFeed Лента клиента
	// (GET /feed)
	ListFeed(ctx echo.Context, params ListFeedParams) error
	// Health Проверка живости
	// (GET /health)
	Health(ctx echo.Context) error
	// Login Вход
	// (POST /login)
	Login(ctx echo.Context) error
	// Logout Выход
	// (POST /logout)
	Logout(ctx echo.Context) error
	// Me Текущий пользователь и его компании
	// (GET /me)
	Me(ctx echo.Context) error
	// ListProducts Продукты
	// (GET /products)
	ListProducts(ctx echo.Context) error
	// RecommendProducts Подбор продукта по цели
	// (GET /products/recommendation)
	RecommendProducts(ctx echo.Context, params RecommendProductsParams) error
	// BankStats Сводка для дашборда банка
	// (GET /stats)
	BankStats(ctx echo.Context, params BankStatsParams) error
}

